// AppHandler 实现：把 CEF 回调转交面板窗口，并经命名管道回报状态
#include "server/app_handler.h" // 自身声明
#include "include/wrapper/cef_helpers.h" // CEF_REQUIRE_UI_THREAD
#include "uis/app_window.h" // AppWindow 接口
#include "uis/ui_chrome.h" // UiChrome（下载列表）
#include "utils/json_util.h" // MakeDict
#include "server/pipe_client.h" // Alive/PostEvent
#include "utils/logging.h" // 文件日志
namespace {
std::string DialogTypeName(AppHandler::JSDialogType type) { return type == JSDIALOGTYPE_PROMPT ? "prompt" : (type == JSDIALOGTYPE_CONFIRM ? "confirm" : "alert"); } // 弹窗类型名归一
}
AppHandler::AppHandler(AppWindow* window) : window_(window) {} // 绑定窗口
void AppHandler::OnAfterCreated(CefRefPtr<CefBrowser> browser) { CEF_REQUIRE_UI_THREAD(); if (!browser_) { browser_ = browser; LOG_INFO("cef", QStringLiteral("浏览器已创建，标识=%1").arg(browser != nullptr ? browser->GetIdentifier() : 0)); if (window_) window_->OnBrowserCreated(browser, this); } } // 首个浏览器创建：登记并通知窗口
void AppHandler::OnBeforeClose(CefRefPtr<CefBrowser> browser) { CEF_REQUIRE_UI_THREAD(); if (browser_ == browser) { LOG_INFO("cef", QStringLiteral("浏览器即将关闭，标识=%1").arg(browser != nullptr ? browser->GetIdentifier() : 0)); dialog_callback_ = nullptr; browser_ = nullptr; NotifyNavWaiters(); if (window_) window_->OnBrowserClosed(browser); } } // 浏览器关闭：清弹窗回调并通知窗口
bool AppHandler::OnBeforePopup(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, const CefString& target_url, const CefString& target_frame_name, cef_window_open_disposition_t target_disposition, bool user_gesture, const CefPopupFeatures& popupFeatures, CefWindowInfo& windowInfo, CefRefPtr<CefClient>& client, CefBrowserSettings& settings, CefRefPtr<CefDictionaryValue>& extra_info, bool* no_javascript_access) { CEF_REQUIRE_UI_THREAD(); LOG_INFO("cef", QStringLiteral("弹窗转标签页：%1").arg(QString::fromStdString(target_url.ToString()))); if (window_) window_->OpenPopup(target_url.ToWString()); return true; } // 不另开 CEF 窗口：新窗口/新标签请求统一转成面板内标签页
void AppHandler::OnTitleChange(CefRefPtr<CefBrowser> browser, const CefString& title) { CEF_REQUIRE_UI_THREAD(); if (window_) window_->OnTitle(browser, title.ToWString()); } // 标题转交窗口
void AppHandler::OnAddressChange(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, const CefString& url) { CEF_REQUIRE_UI_THREAD(); if (frame->IsMain() && window_) window_->OnAddress(browser, url.ToWString()); } // 仅主框架地址转交窗口
bool AppHandler::OnConsoleMessage(CefRefPtr<CefBrowser> browser, cef_log_severity_t level, const CefString& message, const CefString& source, int line) { CEF_REQUIRE_UI_THREAD(); if (window_) window_->OnConsole(browser, level, message.ToString(), source.ToString(), line); return false; } // 控制台消息采集，不拦截默认输出
void AppHandler::OnLoadingStateChange(CefRefPtr<CefBrowser> browser, bool isLoading, bool canGoBack, bool canGoForward) { CEF_REQUIRE_UI_THREAD(); if (window_) window_->OnLoadingState(browser, isLoading, canGoBack, canGoForward); } // 加载状态转交窗口（驱动后退/前进按钮）
void AppHandler::OnLoadEnd(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, int httpStatusCode) { CEF_REQUIRE_UI_THREAD(); (void)browser; (void)httpStatusCode; if (frame != nullptr && frame->IsMain()) { ++nav_seq_; NotifyNavWaiters(); } } // 主框架加载完成：递增序号并唤醒等待者
void AppHandler::OnLoadError(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, ErrorCode errorCode, const CefString& errorText, const CefString& failedUrl) { CEF_REQUIRE_UI_THREAD(); (void)browser; (void)errorText; (void)failedUrl; if (frame != nullptr && frame->IsMain() && errorCode != ERR_ABORTED) { ++nav_seq_; NotifyNavWaiters(); } } // 主框架加载错误（非取消）：递增序号并唤醒等待者
bool AppHandler::OnBeforeBrowse(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, CefRefPtr<CefRequest> request, bool user_gesture, bool is_redirect) { CEF_REQUIRE_UI_THREAD(); return false; } // 导航一律放行
bool AppHandler::OnOpenURLFromTab(CefRefPtr<CefBrowser> browser, CefRefPtr<CefFrame> frame, const CefString& target_url, cef_window_open_disposition_t target_disposition, bool user_gesture) { CEF_REQUIRE_UI_THREAD(); if (target_disposition != WOD_CURRENT_TAB && window_) { window_->OpenPopup(target_url.ToWString()); return true; } return false; } // target=_blank 转本面板新标签
bool AppHandler::OnJSDialog(CefRefPtr<CefBrowser> browser, const CefString& origin_url, JSDialogType dialog_type, const CefString& message_text, const CefString& default_prompt_text, CefRefPtr<CefJSDialogCallback> callback, bool& suppress_message) { CEF_REQUIRE_UI_THREAD(); if (!PipeClient::Alive()) return false; dialog_callback_ = callback; dialog_message_ = message_text.ToString(); dialog_type_ = DialogTypeName(dialog_type); LOG_INFO("cef", QStringLiteral("页面弹窗转交智能体：类型=%1，正文=%2").arg(QString::fromStdString(dialog_type_)).arg(QString::fromStdString(dialog_message_).left(80))); CefRefPtr<CefDictionaryValue> data = MakeDict(); data->SetString("type", dialog_type_); data->SetString("message", dialog_message_); data->SetString("url", origin_url.ToString()); data->SetString("defaultText", default_prompt_text.ToString()); PipeClient::PostEvent("dialog", data); NotifyNavWaiters(); return true; } // 独立调试（未接管道）保留 CEF 原生弹窗；受控模式下转 browser_handle_dialog 应答，并唤醒导航/稳定等待避免死锁
bool AppHandler::OnBeforeUnloadDialog(CefRefPtr<CefBrowser> browser, const CefString& message_text, bool isReload, CefRefPtr<CefJSDialogCallback> callback) { CEF_REQUIRE_UI_THREAD(); if (!PipeClient::Alive()) return false; callback->Continue(true, CefString()); return true; } // beforeunload 直接放行，避免智能体导航被离开确认框卡住
void AppHandler::OnResetDialogState(CefRefPtr<CefBrowser> browser) { CEF_REQUIRE_UI_THREAD(); dialog_callback_ = nullptr; } // 弹窗状态复位
void AppHandler::OnBeforeDownload(CefRefPtr<CefBrowser> browser, CefRefPtr<CefDownloadItem> download_item, const CefString& suggested_name, CefRefPtr<CefBeforeDownloadCallback> callback) { CEF_REQUIRE_UI_THREAD(); (void)browser; (void)download_item; callback->Continue(suggested_name, true); } // 不自建下载 UI：沿用 CEF 默认路径并弹系统对话框（下载列表已随 AI 场景裁剪移除）
void AppHandler::OnDownloadUpdated(CefRefPtr<CefBrowser> browser, CefRefPtr<CefDownloadItem> download_item, CefRefPtr<CefDownloadItemCallback> callback) { (void)browser; (void)download_item; (void)callback; } // 下载进度不再维护列表（列表 UI 与 ui_downloads 指令已移除）
void AppHandler::HandleDialog(bool accept, const std::string& prompt_text) { CEF_REQUIRE_UI_THREAD(); if (dialog_callback_ == nullptr) return; dialog_callback_->Continue(accept, CefString(prompt_text)); dialog_callback_ = nullptr; } // 应答弹窗并释放回调
void AppHandler::AddNavWaiter(std::function<void()> cb) { CEF_REQUIRE_UI_THREAD(); if (cb) nav_waiters_.push_back(std::move(cb)); }
void AppHandler::NotifyNavWaiters() { CEF_REQUIRE_UI_THREAD(); if (nav_waiters_.empty()) return; std::vector<std::function<void()>> list; list.swap(nav_waiters_); for (auto& cb : list) { if (cb) cb(); } }
